-- Texts for the privacy policy, the terms of use, and the links that lead to them.
INSERT INTO translations (locale, key, text) VALUES
    ('es-CO', 'legal.nav', 'Documentos legales'),
    ('en', 'legal.nav', 'Legal documents'),
    ('es-CO', 'legal.back', 'Volver'),
    ('en', 'legal.back', 'Go back'),
    ('es-CO', 'legal.updated', 'Última actualización: 20 de noviembre de 2026.'),
    ('en', 'legal.updated', 'Last updated: 20 November 2026.'),
    ('es-CO', 'legal.privacy.link', 'Política de privacidad'),
    ('en', 'legal.privacy.link', 'Privacy policy'),
    ('es-CO', 'legal.terms.link', 'Términos de uso'),
    ('en', 'legal.terms.link', 'Terms of use'),
    ('es-CO', 'legal.accept', 'Al crear una cuenta aceptas los {terms} y la {privacy}.'),
    ('en', 'legal.accept', 'By creating an account you accept the {terms} and the {privacy}.'),
    ('es-CO', 'legal.privacy.title', 'Política de privacidad'),
    ('en', 'legal.privacy.title', 'Privacy policy'),
    ('es-CO', 'legal.privacy.lead', 'Qué datos guarda HayPaComer, para qué los usa y cómo puedes pedir que los corrijamos o los borremos.'),
    ('en', 'legal.privacy.lead', 'What HayPaComer keeps, what it uses it for, and how you can ask us to correct or delete it.'),
    ('es-CO', 'legal.privacy.who.title', 'Quién responde por tus datos'),
    ('en', 'legal.privacy.who.title', 'Who is responsible for your data'),
    ('es-CO', 'legal.privacy.who.text', 'HayPaComer es un proyecto académico de Ingeniería de Sistemas de la Universidad Cooperativa de Colombia, sede Pasto. Los responsables del tratamiento de tus datos son Juan Camilo López Díaz y Jenifer Urbano.
Para cualquier pregunta, corrección o solicitud de borrado escribe a juanca110720@gmail.com.
Tratamos tus datos según la Ley 1581 de 2012 y el Decreto 1377 de 2013 de Colombia.'),
    ('en', 'legal.privacy.who.text', 'HayPaComer is an academic Systems Engineering project at Universidad Cooperativa de Colombia, Pasto campus. Juan Camilo López Díaz and Jenifer Urbano are responsible for processing your data.
For any question, correction or deletion request, write to juanca110720@gmail.com.
We process your data under Colombian Law 1581 of 2012 and Decree 1377 of 2013.'),
    ('es-CO', 'legal.privacy.data.title', 'Qué datos guardamos'),
    ('en', 'legal.privacy.data.title', 'What we keep'),
    ('es-CO', 'legal.privacy.data.text', '- Tu cuenta: nombre, correo, idioma y una huella cifrada de tu contraseña. Nunca guardamos ni vemos tu contraseña.
- Tu hogar: su nombre, sus miembros y el papel de cada uno.
- Tu cocina: la comida de tu nevera con sus gramos y fechas, los cambios que haces, la lista de mercado, el presupuesto, los precios, las recetas, el plan de la semana y las sesiones de cocina.
- Tus dispositivos: las lecturas de puerta, temperatura y peso que envían los sensores que registras.
- Tus avisos: las notificaciones del hogar y, si lo activas, tu identificador de chat de Telegram.
- El Chef: tus preguntas, sus respuestas y las notas que el hogar le pide recordar.
- Seguridad: los intentos de inicio de sesión y un registro de quién cambió qué y cuándo.'),
    ('en', 'legal.privacy.data.text', '- Your account: name, email, language and an encrypted fingerprint of your password. We never store or see your password.
- Your household: its name, its members and each member''s role.
- Your kitchen: the food in your fridge with its grams and dates, the changes you make, the market list, the budget, prices, recipes, the weekly plan and cooking sessions.
- Your devices: the door, temperature and weight readings sent by the sensors you register.
- Your alerts: household notifications and, if you turn it on, your Telegram chat ID.
- The Chef: your questions, its answers and the notes your household asks it to remember.
- Security: sign-in attempts and a log of who changed what and when.'),
    ('es-CO', 'legal.privacy.health.title', 'Alergias y dietas'),
    ('en', 'legal.privacy.health.title', 'Allergies and diets'),
    ('es-CO', 'legal.privacy.health.text', 'Tus alergias, tu dieta y los alimentos que evitas pueden revelar datos de salud, que la ley considera sensibles. No estás obligado a darlos.
Si los das, solo los usamos para avisarte cuando una comida o una receta no te conviene, y solo los ven los miembros de tu hogar al cocinar para ti.'),
    ('en', 'legal.privacy.health.text', 'Your allergies, diet and the foods you avoid may reveal health information, which the law treats as sensitive. You do not have to give it.
If you do, we only use it to warn you when a food or a recipe does not suit you, and only the members of your household see it when cooking for you.'),
    ('es-CO', 'legal.privacy.use.title', 'Para qué los usamos'),
    ('en', 'legal.privacy.use.title', 'What we use it for'),
    ('es-CO', 'legal.privacy.use.text', 'Solo para que la app funcione: mostrar tu nevera, avisar cuando algo vence o la nevera se calienta, sugerir qué cocinar, armar tu mercado y calcular cuánto ahorras.
No vendemos tus datos, no mostramos publicidad y no los usamos para perfiles comerciales.'),
    ('en', 'legal.privacy.use.text', 'Only to make the app work: show your fridge, warn you when food expires or the fridge warms up, suggest what to cook, build your market list and work out how much you save.
We do not sell your data, show ads or use it for commercial profiling.'),
    ('es-CO', 'legal.privacy.ai.title', 'El asistente de cocina'),
    ('en', 'legal.privacy.ai.title', 'The cooking assistant'),
    ('es-CO', 'legal.privacy.ai.text', 'Hoy el Chef funciona con reglas propias dentro de nuestro servidor, sin enviar nada a terceros.
Si activamos un proveedor de inteligencia artificial (como Google Gemini), le enviaríamos solo lo necesario para responder: nombres de alimentos, gramos, fechas, minutos de las recetas, el texto de tu pregunta y las fotos de recetas o etiquetas que tú subas. Nunca tu nombre, tu correo ni tu contraseña.
El Chef no cambia nada por su cuenta: toda acción espera tu confirmación.'),
    ('en', 'legal.privacy.ai.text', 'Today the Chef runs on our own rules inside our server and sends nothing to third parties.
If we turn on an artificial intelligence provider (such as Google Gemini), we would send it only what it needs to answer: food names, grams, dates, recipe minutes, the text of your question and the recipe or label photos you upload. Never your name, email or password.
The Chef changes nothing on its own: every action waits for your confirmation.'),
    ('es-CO', 'legal.privacy.where.title', 'Dónde se guardan'),
    ('en', 'legal.privacy.where.title', 'Where it is stored'),
    ('es-CO', 'legal.privacy.where.text', 'En un servidor de Amazon Web Services en Virginia, Estados Unidos. Al usar la app autorizas esta transferencia internacional; Amazon solo aloja los datos y no los usa para otros fines.
Toda conexión con la app va cifrada (HTTPS).'),
    ('en', 'legal.privacy.where.text', 'On an Amazon Web Services server in Virginia, United States. By using the app you authorise this international transfer; Amazon only hosts the data and does not use it for anything else.
Every connection to the app is encrypted (HTTPS).'),
    ('es-CO', 'legal.privacy.shared.title', 'Quién más los ve'),
    ('en', 'legal.privacy.shared.title', 'Who else sees it'),
    ('es-CO', 'legal.privacy.shared.text', '- Los miembros de tu hogar ven la comida compartida, el mercado y la actividad. La comida marcada como privada solo la ves tú y quien tú autorices.
- Telegram recibe tus avisos solo si conectas tu chat.
- Amazon Web Services aloja el servidor.
- Las autoridades, solo si una orden legal nos obliga.'),
    ('en', 'legal.privacy.shared.text', '- Your household members see shared food, the market list and activity. Food marked private is seen only by you and whoever you allow.
- Telegram receives your alerts only if you connect your chat.
- Amazon Web Services hosts the server.
- Authorities, only if a legal order requires it.'),
    ('es-CO', 'legal.privacy.browser.title', 'En tu navegador'),
    ('en', 'legal.privacy.browser.title', 'In your browser'),
    ('es-CO', 'legal.privacy.browser.text', 'No usamos cookies de seguimiento, analítica ni publicidad.
Tu navegador guarda tu sesión, tu idioma, el tema claro u oscuro y si quieres sonido. Al cerrar sesión se borra la sesión.'),
    ('en', 'legal.privacy.browser.text', 'We use no tracking, analytics or advertising cookies.
Your browser keeps your session, your language, light or dark theme and whether you want sound. Signing out deletes the session.'),
    ('es-CO', 'legal.privacy.time.title', 'Cuánto tiempo los guardamos'),
    ('en', 'legal.privacy.time.title', 'How long we keep it'),
    ('es-CO', 'legal.privacy.time.text', 'Mientras tengas tu cuenta y dure el proyecto. Las conversaciones con el Chef se borran solas a los 7 días sin uso y el registro de lo que hizo, a los 30 días.
Si pides borrar tu cuenta, borramos tus datos en máximo 15 días hábiles, salvo lo que la ley nos obligue a conservar. Al terminar el proyecto borraremos el servidor completo.'),
    ('en', 'legal.privacy.time.text', 'For as long as you keep your account and the project runs. Chef conversations delete themselves after 7 days without use, and the record of what it did after 30 days.
If you ask us to delete your account, we delete your data within 15 business days, except what the law requires us to keep. When the project ends we will delete the whole server.'),
    ('es-CO', 'legal.privacy.rights.title', 'Tus derechos'),
    ('en', 'legal.privacy.rights.title', 'Your rights'),
    ('es-CO', 'legal.privacy.rights.text', 'Según la Ley 1581 de 2012 puedes, gratis:
- Conocer, actualizar y corregir tus datos.
- Pedir prueba de tu autorización y saber cómo usamos tus datos.
- Retirar tu autorización y pedir que borremos tus datos.
- Quejarte ante la Superintendencia de Industria y Comercio si no respetamos estos derechos.
Escríbenos a juanca110720@gmail.com desde el correo de tu cuenta. Respondemos las consultas en máximo 10 días hábiles y los reclamos en máximo 15 días hábiles.'),
    ('en', 'legal.privacy.rights.text', 'Under Law 1581 of 2012 you can, free of charge:
- Know, update and correct your data.
- Ask for proof of your authorisation and learn how we use your data.
- Withdraw your authorisation and ask us to delete your data.
- Complain to the Superintendence of Industry and Commerce if we do not respect these rights.
Write to juanca110720@gmail.com from your account''s email. We answer questions within 10 business days and claims within 15 business days.'),
    ('es-CO', 'legal.privacy.minors.title', 'Menores de edad'),
    ('en', 'legal.privacy.minors.title', 'Minors'),
    ('es-CO', 'legal.privacy.minors.text', 'Las cuentas son para mayores de 18 años. Un menor puede usar la app dentro del hogar de un adulto responsable, que autoriza y responde por su uso.'),
    ('en', 'legal.privacy.minors.text', 'Accounts are for people aged 18 or over. A minor may use the app inside the household of a responsible adult, who authorises and answers for that use.'),
    ('es-CO', 'legal.privacy.changes.title', 'Cambios a esta política'),
    ('en', 'legal.privacy.changes.title', 'Changes to this policy'),
    ('es-CO', 'legal.privacy.changes.text', 'Si cambiamos algo importante, te avisaremos en la app antes de que el cambio aplique.'),
    ('en', 'legal.privacy.changes.text', 'If we change anything important, we will tell you in the app before the change applies.'),
    ('es-CO', 'legal.terms.title', 'Términos de uso'),
    ('en', 'legal.terms.title', 'Terms of use'),
    ('es-CO', 'legal.terms.lead', 'Las reglas para usar HayPaComer. Al crear una cuenta las aceptas.'),
    ('en', 'legal.terms.lead', 'The rules for using HayPaComer. You accept them when you create an account.'),
    ('es-CO', 'legal.terms.what.title', 'Qué es HayPaComer'),
    ('en', 'legal.terms.what.title', 'What HayPaComer is'),
    ('es-CO', 'legal.terms.what.text', 'Un proyecto académico de la Universidad Cooperativa de Colombia, sede Pasto: un prototipo gratuito que mide tu nevera y te ayuda a cocinar con lo que hay.
Al ser un prototipo, puede tener fallas, cambiar sin aviso o quedar fuera de línea.'),
    ('en', 'legal.terms.what.text', 'An academic project at Universidad Cooperativa de Colombia, Pasto campus: a free prototype that measures your fridge and helps you cook with what you have.
Being a prototype, it may fail, change without notice or go offline.'),
    ('es-CO', 'legal.terms.account.title', 'Tu cuenta'),
    ('en', 'legal.terms.account.title', 'Your account'),
    ('es-CO', 'legal.terms.account.text', 'Usa tus datos reales y una contraseña que no uses en otro sitio. Eres responsable de lo que se haga con tu cuenta y con las claves de los dispositivos que registres.
Si crees que alguien entró a tu cuenta, cambia tu contraseña y escríbenos.'),
    ('en', 'legal.terms.account.text', 'Use your real details and a password you do not use anywhere else. You are responsible for what is done with your account and with the keys of the devices you register.
If you think someone got into your account, change your password and write to us.'),
    ('es-CO', 'legal.terms.household.title', 'Tu hogar'),
    ('en', 'legal.terms.household.title', 'Your household'),
    ('es-CO', 'legal.terms.household.text', 'Quien crea el hogar es su dueño: invita y retira miembros y decide qué puede hacer cada uno. Lo que agregas al hogar lo ven sus miembros, salvo la comida que marques como privada.'),
    ('en', 'legal.terms.household.text', 'Whoever creates the household owns it: they invite and remove members and decide what each one can do. What you add to the household is visible to its members, except food you mark as private.'),
    ('es-CO', 'legal.terms.food.title', 'Seguridad de los alimentos'),
    ('en', 'legal.terms.food.title', 'Food safety'),
    ('es-CO', 'legal.terms.food.text', 'Las fechas estimadas, las alertas de temperatura y las sugerencias son una ayuda, no una garantía. Revisa siempre el olor, el aspecto y la etiqueta, y ante la duda no lo comas.
Si tienes alergias, verifica siempre los ingredientes. HayPaComer no reemplaza el consejo de un médico ni de un nutricionista.'),
    ('en', 'legal.terms.food.text', 'Estimated dates, temperature alerts and suggestions are a help, not a guarantee. Always check the smell, the look and the label, and when in doubt, do not eat it.
If you have allergies, always check the ingredients. HayPaComer does not replace advice from a doctor or a nutritionist.'),
    ('es-CO', 'legal.terms.chef.title', 'El Chef'),
    ('en', 'legal.terms.chef.title', 'The Chef'),
    ('es-CO', 'legal.terms.chef.text', 'El Chef puede equivocarse. Nunca cambia tu nevera, tu mercado ni tu cocina sin tu confirmación: lee bien lo que propone antes de aprobarlo.'),
    ('en', 'legal.terms.chef.text', 'The Chef can be wrong. It never changes your fridge, your market list or your cooking without your confirmation: read what it proposes before you approve it.'),
    ('es-CO', 'legal.terms.kit.title', 'El kit de sensores'),
    ('en', 'legal.terms.kit.title', 'The sensor kit'),
    ('es-CO', 'legal.terms.kit.text', 'El kit (sensor de puerta, sonda de temperatura y báscula) es experimental y funciona a 5 V por USB. Instálalo sin perforar ni modificar tu nevera y pasa los cables por el empaque sin dañarlo. La instalación corre por tu cuenta.'),
    ('en', 'legal.terms.kit.text', 'The kit (door sensor, temperature probe and scale) is experimental and runs on 5 V over USB. Install it without drilling into or modifying your fridge, and run the cables along the door seal without damaging it. You install it at your own risk.'),
    ('es-CO', 'legal.terms.conduct.title', 'Uso aceptable'),
    ('en', 'legal.terms.conduct.title', 'Acceptable use'),
    ('es-CO', 'legal.terms.conduct.text', '- No intentes entrar a cuentas u hogares ajenos ni atacar o saturar el servicio.
- No subas fotos ni textos ilegales, ofensivos o que no te pertenezcan.
- No uses la app para fines comerciales sin nuestro permiso.
Podemos suspender las cuentas que incumplan estas reglas.'),
    ('en', 'legal.terms.conduct.text', '- Do not try to get into other people''s accounts or households, or attack or overload the service.
- Do not upload photos or text that are illegal, offensive or not yours.
- Do not use the app for commercial purposes without our permission.
We may suspend accounts that break these rules.'),
    ('es-CO', 'legal.terms.liability.title', 'Responsabilidad'),
    ('en', 'legal.terms.liability.title', 'Liability'),
    ('es-CO', 'legal.terms.liability.text', 'Ofrecemos la app tal como está y sin costo. En la medida en que lo permite la ley colombiana, no respondemos por comida dañada, pérdidas, daños a tus equipos ni interrupciones del servicio.'),
    ('en', 'legal.terms.liability.text', 'We offer the app as it is and free of charge. To the extent Colombian law allows, we are not liable for spoiled food, losses, damage to your equipment or service interruptions.'),
    ('es-CO', 'legal.terms.end.title', 'Fin del servicio'),
    ('en', 'legal.terms.end.title', 'End of the service'),
    ('es-CO', 'legal.terms.end.text', 'Puedes dejar de usar la app y pedir que borremos tu cuenta cuando quieras. Si el proyecto termina, te avisaremos con tiempo para que descargues tus reportes antes de borrar el servidor.'),
    ('en', 'legal.terms.end.text', 'You can stop using the app and ask us to delete your account at any time. If the project ends, we will give you notice so you can download your reports before we delete the server.'),
    ('es-CO', 'legal.terms.law.title', 'Ley aplicable y contacto'),
    ('en', 'legal.terms.law.title', 'Governing law and contact'),
    ('es-CO', 'legal.terms.law.text', 'Estos términos se rigen por las leyes de Colombia. Para cualquier duda escribe a juanca110720@gmail.com.'),
    ('en', 'legal.terms.law.text', 'These terms are governed by the laws of Colombia. For any question write to juanca110720@gmail.com.')
ON CONFLICT (locale, key) DO UPDATE SET text = EXCLUDED.text, updated_at = now();
